static lstr L10795 = {0, 1368, "// std/atomic: Atomic<T>, a bool or an integer with atomic operations (SPEC.md\012// section 8, D111 item 4).\012//\012// T is bool or an integer type up to 64 bits (E1411 otherwise). Every\012// operation is sequentially consistent. Copies of an Atomic are handles to\012// one value. Importing this module builds the program in thread mode (D111\012// item 2).\012\012import * as Boxes from \"std/box\"\012import * as Threads from \"std/internal/thread\"\012\012export opaque struct Atomic<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Atomic<T> uses alloc {\012  return Atomic { slot: Boxes.new(value) }\012}\012\012export function load<T>(atomic: Atomic<T>): T {\012  return Threads.atomicLoad(atomic.slot)\012}\012\012export function store<T>(atomic: Atomic<T>, value: T) {\012  Threads.atomicStore(atomic.slot, value)\012}\012\012// Stores value and gives the value it replaced.\012export function exchange<T>(atomic: Atomic<T>, value: T): T {\012  return Threads.atomicExchange(atomic.slot, value)\012}\012\012// Adds amount and gives the old value. The sum wraps, like + (D92).\012export function add<T>(atomic: Atomic<T>, amount: T): T {\012  return Threads.atomicAdd(atomic.slot, amount)\012}\012\012// Stores replacement when the value is expected, and tells whether it stored.\012export function compareExchange<T>(atomic: Atomic<T>, expected: T, replacement: T): bool {\012  return Threads.atomicCompareExchange(atomic.slot, expected, replacement)\012}\012"};
static lstr L10796 = {0, 9, "std/build"};
static lstr L10797 = {0, 1339, "// std/build: the target a program is built for. The compiler sets os, arch and\012// debug for each build; the values written here are replaced. An `if` that\012// tests only these constants keeps one branch in the output.\012\012import * as Host from \"std/internal/host\"\012\012export enum Os derives Show, Equatable {\012  MacOS\012  Linux\012  Windows\012  Wasi\012}\012\012export enum Arch derives Show, Equatable {\012  Arm64\012  X86_64\012  Wasm32\012}\012\012export const os: Os = Os.Linux\012export const arch: Arch = Arch.X86_64\012export const debug: bool = true\012\012export struct Target {\012  os: Os\012  arch: Arch\012}\012\012export function hostTarget(): Option<Target> {\012  const hostOs = Host.os()\012  const hostArch = Host.arch()\012  // The C compiler's predefined macros give the codes; 0 is a machine with no variant here.\012  if (hostOs == 0 || hostArch == 0) {\012    return None\012  }\012  if (hostOs == 1 && hostArch == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.Arm64 })\012  }\012  if (hostOs == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.X86_64 })\012  }\012  if (hostOs == 3 && hostArch == 1) {\012    return Some(Target { os: Os.Windows, arch: Arch.Arm64 })\012  }\012  if (hostOs == 3) {\012    return Some(Target { os: Os.Windows, arch: Arch.X86_64 })\012  }\012  if (hostArch == 1) {\012    return Some(Target { os: Os.Linux, arch: Arch.Arm64 })\012  }\012  return Some(Target { os: Os.Linux, arch: Arch.X86_64 })\012}\012"};
static lstr L10798 = {0, 8, "std/cell"};
static lstr L10799 = {0, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
static lstr L10800 = {0, 11, "std/channel"};
static lstr L10801 = {0, 5348, "// std/channel: bounded channels between threads (SPEC.md section 8, D111 item 4).\012//\012// Channel.create gives a Sender and a Receiver over one queue of a fixed\012// number of slots. send blocks while the queue is full, receive blocks while it\012// is empty. Copies of an end share it; when the last copy of the sender is\012// dropped the channel closes, and when the last copy of the receiver is\012// dropped send gives false. Importing this module builds the program in thread\012// mode (D111 item 2).\012\012import * as Arrays from \"std/array\"\012import * as Boxes from \"std/box\"\012import * as CellSlot from \"std/internal/cell\"\012import * as Threads from \"std/internal/thread\"\012\012// The conditions of the Sync: a value was queued (or the channel closed), and\012// a slot was freed.\012const VALUE_READY = 0\012const ROOM_READY = 1\012\012// The end counts of the Sync.\012const SENDERS = 0\012const RECEIVERS = 1\012\012// Where the oldest value is, how many values wait, and whether close ran.\012// Read and written only with the lock held.\012struct QueueState {\012  head: int\012  count: int\012  closed: bool\012}\012\012// The ring of slots, each a box of its own, so a send or a receive writes one\012// slot in place and never copies the ring.\012struct Queue<T> {\012  sync: Sync\012  state: Box<QueueState>\012  slots: Array<Box<Option<T>>>\012}\012\012export opaque struct Sender<T> {\012  queue: Queue<T>\012  end: Sync\012}\012\012export opaque struct Receiver<T> {\012  queue: Queue<T>\012  end: Sync\012}\012\012// A channel with room for capacity values; a capacity below 1 is 1. The\012// element type must be Sendable (E1190).\012export function create<T>(capacity: int): #[Sender<T>, Receiver<T>] uses alloc {\012  let size = capacity\012  if (size < 1) {\012    size = 1\012  }\012  let slots: Array<Box<Option<T>>> = []\012  for (let index = 0; index < size; index++) {\012    const slot: Box<Option<T>> = Boxes.new(None)\012    Arrays.push(mutable slots, slot)\012  }\012  const sync = Threads.sync()\012  const queue = Queue {\012    sync,\012    state: Boxes.new(QueueState { head: 0, count: 0, closed: false }),\012    slots,\012  }\012  const sender = Sender { queue, end: Threads.end(sync, SENDERS) }\012  const receiver = Receiver { queue, end: Threads.end(sync, RECEIVERS) }\012  return #[sender, receiver]\012}\012\012// Queues value, waiting while the channel is full. Gives false, and keeps\012// nothing, once the channel is closed or every receiver is gone.\012export function send<T>(sender: Sender<T>, value: T): bool uses io {\012  const queue = sender.queue\012  // The value is marked shared before a receiver on another thread can reach it.\012  Threads.share(value)\012  Threads.lock(queue.sync)\012  while (canSend(queue) && queue.state.value.count == Arrays.length(queue.slots)) {\012    Threads.wait(queue.sync, ROOM_READY)\012  }\012  if (!canSend(queue)) {\012    Threads.unlock(queue.sync)\012    return false\012  }\012  const state = queue.state.value\012  const tail = wrapSlot(state.head + state.count, Arrays.length(queue.slots))\012  CellSlot.store(queue.slots[tail], Some(value))\012  CellSlot.store(queue.state, QueueState {\012    head: state.head,\012    count: state.count + 1,\012    closed: false,\012  })\012  Threads.wakeOne(queue.sync, VALUE_READY)\012  Threads.unlock(queue.sync)\012  return true\012}\012\012// Takes the oldest value, waiting while the channel is empty. Gives None once\012// the channel is closed and empty.\012export function receive<T>(receiver: Receiver<T>): Option<T> uses io {\012  const queue = receiver.queue\012  Threads.lock(queue.sync)\012  while (queue.state.value.count == 0 && isOpen(queue)) {\012    Threads.wait(queue.sync, VALUE_READY)\012  }\012  if (queue.state.value.count == 0) {\012    Threads.unlock(queue.sync)\012    return None\012  }\012  const state = queue.state.value\012  // The value moves out of its slot, so the receiver holds the only reference.\012  const value = Threads.take(queue.slots[state.head])\012  CellSlot.store(queue.state, QueueState {\012    head: wrapSlot(state.head + 1, Arrays.length(queue.slots)),\012    count: state.count - 1,\012    closed: state.closed,\012  })\012  Threads.wakeOne(queue.sync, ROOM_READY)\012  Threads.unlock(queue.sync)\012  return value\012}\012\012// The values of the channel, in the order they were sent, until it is closed and empty.\012export function* values<T>(receiver: Receiver<T>): Generator<T> uses io {\012  let open = true\012  while (open) {\012    const next = receive(receiver)\012    if (next is Some(value)) {\012      yield value\012    } else {\012      open = false\012    }\012  }\012}\012\012// Closes the channel for every copy of the sender. The values already queued\012// can still be received.\012export function close<T>(sender: Sender<T>) {\012  const queue = sender.queue\012  Threads.lock(queue.sync)\012  const state = queue.state.value\012  CellSlot.store(queue.state, QueueState { head: state.head, count: state.count, closed: true })\012  Threads.wakeAll(queue.sync, VALUE_READY)\012  Threads.wakeAll(queue.sync, ROOM_READY)\012  Threads.unlock(queue.sync)\012}\012\012// With the lock held: the channel takes values while it is not closed and a receiver is left.\012function canSend<T>(queue: Queue<T>): bool {\012  return !queue.state.value.closed && Threads.ends(queue.sync, RECEIVERS) > 0\012}\012\012// With the lock held: more values can come while it is not closed and a sender is left.\012function isOpen<T>(queue: Queue<T>): bool {\012  return !queue.state.value.closed && Threads.ends(queue.sync, SENDERS) > 0\012}\012\012// The slot a position past the end of the ring comes back to.\012function wrapSlot(position: int, size: int): int {\012  if (size == 0) {\012    return 0\012  }\012  return position % size\012}\012"};
static lstr L10802 = {0, 13, "std/coroutine"};
static lstr L10803 = {0, 1073, "// std/coroutine: Co.resume runs a generator to its next yield, and Co.send runs\012// a coroutine to its next yield with an input.\012//\012// The compiler turns `Co.resume(mutable g)` into resumeGenerator and\012// `Co.send(mutable g, input)` into resumeCoroutine.\012\012import * as Internal from \"std/internal/coroutine\"\012\012export enum Step<Out> derives Show, Equatable {\012  Yielded(value: Out)\012  Done\012  Panicked(message: string)\012}\012\012export function resumeGenerator<T, effect E>(\012  mutable g: Generator<T> uses E,\012): Step<T> uses E, alloc {\012  return readStep(Internal.next(mutable g))\012}\012\012export function resumeCoroutine<In, Out, effect E>(\012  mutable g: Coroutine<In, Out> uses E,\012  input: In,\012): Step<Out> uses E, alloc {\012  return readStep(Internal.resume(mutable g, input))\012}\012\012// readStep reads the outcome of one resume: a value, the end, or a panic.\012function readStep<T>(next: Option<T>): Step<T> from next uses alloc {\012  if (next is Some(value)) {\012    return Step.Yielded(value)\012  }\012  if (Internal.panicked()) {\012    return Step.Panicked(Internal.panicMessage())\012  }\012  return Step.Done\012}\012"};
static lstr L10804 = {0, 11, "std/cstring"};
static lstr L10805 = {0, 1176, "// std/cstring: CString, a string with no zero byte, which C reads as a zero-terminated string.\012//\012// Pass `CStrings.pointer(text)` to a C function that takes `char*`; the pointer is valid while\012// the CString is. `CStrings.read` copies a zero-terminated string that C returns.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Ptr from \"std/ptr\"\012import * as Text from \"std/internal/cstring\"\012\012export opaque struct CString {\012  text: string\012}\012\012export function from(text: string): Option<CString> {\012  // C would stop at a zero byte, so a string that holds one has no CString.\012  const length = Str.length(text)\012  for (let index = 0; index < length; index++) {\012    if (Str.byteAt(text, index) == 0) {\012      return None\012    }\012  }\012  return Some(CString { text })\012}\012\012export function toString(value: CString): string from value {\012  return value.text\012}\012\012export function pointer(value: CString): Ptr<u8> {\012  return Text.pointer(value.text)\012}\012\012export function read(address: Ptr<u8>): Result<string, string> uses alloc, unsafe {\012  let copied: Result<string, string> = Err(\"\")\012  unsafe {\012    copied = Bytes.toString(Text.read(address))\012  }\012  return copied\012}\012"};
static lstr L10806 = {0, 13, "std/ext/array"};
static lstr L10807 = {0, 834, "// std/array: helpers over Array. The functions that need the compiler are built in.\012\012import * as Arrays from \"std/array\"\012\012export function map<T, U, effect E>(\012  items: Array<T>,\012  change: (value: T) => U uses E,\012): Array<U> uses alloc, E {\012  let result: Array<U> = Arrays.withCapacity(Arrays.length(items))\012  for (const item of items) {\012    Arrays.push(mutable result, change(item))\012  }\012  return result\012}\012\012export function slice<T>(items: Array<T>, start: int, finish: int): Option<Array<T>> uses alloc {\012  // A range outside the array has no slice.\012  if (start < 0 || finish > Arrays.length(items) || start > finish) {\012    return None\012  }\012  let result: Array<T> = Arrays.withCapacity(finish - start)\012  for (let index = start; index < finish; index++) {\012    Arrays.push(mutable result, copy(items[index]))\012  }\012  return Some(result)\012}\012"};
static lstr L10808 = {0, 13, "std/ext/float"};
