static lstr L10845 = {0, 1224, "// std/time: a monotonic clock for measuring, the wall clock, and sleep. Reading a clock or sleeping is `io`.\012\012import * as Clock from \"std/internal/clock\"\012\012export struct Instant {\012  nanos: int\012}\012\012export struct Duration {\012  nanos: int\012}\012\012export function now(): Instant uses io {\012  return Instant { nanos: Clock.monotonicNanos() }\012}\012\012export function elapsed(since: Instant): Duration uses io {\012  return Duration { nanos: Clock.monotonicNanos() - since.nanos }\012}\012\012export function between(earlier: Instant, later: Instant): Duration {\012  return Duration { nanos: later.nanos - earlier.nanos }\012}\012\012export function unixMillis(): int uses io {\012  return Clock.wallMillis()\012}\012\012export function sleep(duration: Duration) uses io {\012  Clock.sleepNanos(duration.nanos)\012}\012\012export function nanoseconds(count: int): Duration {\012  return Duration { nanos: count }\012}\012\012export function milliseconds(count: int): Duration {\012  return Duration { nanos: count * 1000000 }\012}\012\012export function seconds(count: int): Duration {\012  return Duration { nanos: count * 1000000000 }\012}\012\012export function asNanoseconds(duration: Duration): int {\012  return duration.nanos\012}\012\012export function asMilliseconds(duration: Duration): int {\012  return duration.nanos / 1000000\012}\012"};
